-- =====================================================================
--  Хроники Этерны — метки на карте мира (Восточные Чумные земли)
--  Файл: 52_map_markers.sql
--
--  Для каждого квеста 915000-916399 ставится:
--    ObjectiveIndex = -1  — у квестодателя (знак «!»)
--    ObjectiveIndex = 0..3 — круг у цели RequiredNpcOrGo1..4
--    ObjectiveIndex = 4    — круг у источника RequiredItemId1
--  WorldMapAreaId = 23 (Eastern Plaguelands), MapID = 0.
--  Координаты берутся из фактического положения существ.
-- =====================================================================

SET NAMES utf8mb4;

DELETE FROM `quest_poi`         WHERE `QuestID` BETWEEN 915000 AND 916399;
DELETE FROM `quest_poi_points`  WHERE `QuestID` BETWEEN 915000 AND 916399;
DELETE FROM `points_of_interest` WHERE `ID` BETWEEN 911000 AND 911099;



